from build123d import *

total_length = 80.0
base_diameter =  textvariable{base_diameter}
base_thickness = USTARIABLE{base_thickness}
shank_diameter = USTARIABLE{shank_diameter}
shank_length = USTARIABLE{shank_length}
grip_diameter = USTARIABLE{grip_diameter}
grip_length = USTARIABLE{grip_length}
head_diameter = USTARIABLE{head_diameter}

with BuildPart() as p:
    with BuildSketch(Plane.XZ) as sk:
        with BuildLine() as bl:
            Polyline((0,0), (base_diameter/2, 0), (base_diameter/2, base_thickness),
                     (shank_diameter/2, base_thickness + shank_length),
                     (grip_diameter/2, base_thickness + shank_length + grip_length),
                     (head_diameter/2, total_length), (0, total_length), close=True)
        make_face()
    revolve(axis=Axis.Y)

part = p.part
part.name = "revolved_handle"
export_step(part, "output.step")
